        (128, N'100000-001', N'Clinical safety', N'No Clinical Safety Incidents in a calendar month and not resolved within the resolution time', N'Any Clinical Safety Incidents being reported in accordance with DCB0129', 1, GETUTCDATE(), 2),
        (129, N'100000-001', N'Other failures', N'No High Severity Service Incidents in a calendar month and not resolved with resolution time', N'Any High Severity Service Incidents being reported', 1, GETUTCDATE(), 2),
        (130, N'100000-001', N'Service desk performance', N'Applicable service failures and their definitions to be agreed with each supplier', N'To be taken from the approved proposal from the supplier', 1, GETUTCDATE(), 2),
        (131, N'100002-001', N'Catalogue Solution availability including interfaces to national systems', N'99.9% availability during each calendar month and less than 10 minutes downtime in total', N'Measured on a per practice basis by suppliers monitoring tools and reported to service management', 1, GETUTCDATE(), 2),
        (132, N'100002-001', N'Catalogue Solution responsiveness', N'99.9% of transactions take less than 2 seconds', N'Measured per transaction within the boundaries of the suppliers datacentre and reported to service management', 1, GETUTCDATE(), 2),
        (133, N'100002-001', N'Clinical safety', N'No Clinical Safety Incidents in a calendar month and not resolved within the resolution time', N'Any Clinical Safety Incidents being reported in accordance with DCB0129', 1, GETUTCDATE(), 2),
        (134, N'100002-001', N'Other failures', N'No High Severity Service Incidents in a calendar month and not resolved with resolution time', N'Any High Severity Service Incidents being reported', 1, GETUTCDATE(), 2),
        (135, N'100002-001', N'Service desk performance', N'Applicable service failures and their definitions to be agreed with each supplier', N'To be taken from the approved proposal from the supplier', 1, GETUTCDATE(), 2))
    AS SOURCE ([Id], [SolutionId], [TypeOfService], [ServiceLevel], [HowMeasured], [ServiceCredits], [LastUpdated], [LastUpdatedBy])
    ON TARGET.[Id] = SOURCE.[Id]
    WHEN MATCHED THEN UPDATE SET
        TARGET.[SolutionId] = SOURCE.[SolutionId],
        TARGET.[TypeOfService] = SOURCE.[TypeOfService],
        TARGET.[ServiceLevel] = SOURCE.[ServiceLevel],
        TARGET.[HowMeasured] = SOURCE.[HowMeasured],
        TARGET.[ServiceCredits] = SOURCE.[ServiceCredits],
        TARGET.[LastUpdated] = SOURCE.[LastUpdated],
        TARGET.[LastUpdatedBy] = SOURCE.[LastUpdatedBy]
    WHEN NOT MATCHED BY TARGET THEN
        INSERT ([Id], [SolutionId], [TypeOfService], [ServiceLevel], [HowMeasured], [ServiceCredits], [LastUpdated], [LastUpdatedBy])
        VALUES (SOURCE.[Id], SOURCE.[SolutionId], SOURCE.[TypeOfService], SOURCE.[ServiceLevel], SOURCE.[HowMeasured], SOURCE.[ServiceCredits], SOURCE.[LastUpdated], SOURCE.[LastUpdatedBy]);

    SET IDENTITY_INSERT [catalogue].[SlaServiceLevels] OFF
END

